SET name=#{name}, nickname=#{nickname}, email=#{email}, phone_number=#{phone_number}
WHERE id=#{id}

UPDATE users_image
SET origin_filename=#{origin_filename}, hashing_filename=#{hashing_filename}, filesize=#{filesize}
WHERE user_id=#{userId}

mapper.select:
SELECT username
FROM users
WHERE name = #{name} AND email = #{email} AND phone_number = #{phone_number}
